import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const dataDir = path.resolve("data/exams/n1/original");

function seeded(seed) {
  let state = seed >>> 0;
  return () => ((state = (Math.imul(state, 1664525) + 1013904223) >>> 0) / 2 ** 32);
}

function shuffle(values, random) {
  const out = [...values];
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function textLength(text) {
  return Array.from(text.replace(/\s/g, "")).length;
}

function groupId(examNo, mondai, sequence, type = "reading") {
  return `n1-original-${String(examNo).padStart(2, "0")}-${type}-${String(mondai).padStart(2, "0")}-${String(sequence).padStart(2, "0")}`;
}

function reviseExam(examNo, source) {
  const file = path.join(dataDir, `n1-original-${String(examNo).padStart(2, "0")}.json`);
  return { file, source };
}

